import { AuthSignUpCard, mockAuthAdapter } from "@hex-core/components";

<AuthSignUpCard
  adapter={mockAuthAdapter}
  socialProviders={[
    { provider: "github", label: "GitHub" },
    { provider: "google", label: "Google" },
  ]}
  signInHref="/sign-in"
  termsHref="/terms"
  privacyHref="/privacy"
/>
